def transform(grid):
    # Color every other cell along horizontal/vertical runs of 1s, replacing the intervening background.
    h, w = len(grid), len(grid[0])
    out = [r[:] for r in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1:
                continue
            # Identify horizontal or vertical continuous stretches; alternate gaps between separated 1 segments
            # The rule inferred: each maximal straight line of 1s gets its gaps colored 2, using the endpoints.
    # For each row/column, between any two 1s with no other 1 interruption? fill zeros in segment.
    for r in range(h):
        cols=[c for c,v in enumerate(grid[r]) if v==1]
        if len(cols)>1:
            for c in range(cols[0],cols[-1]+1):
                if grid[r][c]==8: out[r][c]=2
    for c in range(w):
        rows=[r for r in range(h) if grid[r][c]==1]
        if len(rows)>1:
            for r in range(rows[0],rows[-1]+1):
                if grid[r][c]==8: out[r][c]=2
    return out
